SELECT spirit_id AS id, name, price, category_id AS categoryId, 'spirit' AS productType, spirit_id AS spiritId
FROM spirits WHERE category_id = #{categoryId}
UNION ALL
SELECT mixer_id AS id, name, price, category_id AS categoryId, 'mixer' AS productType, mixer_id AS mixerId
FROM mixers WHERE category_id = #{categoryId}
UNION ALL
SELECT fruit_id AS id, name, price, category_id AS categoryId, 'fruit' AS productType, fruit_id AS fruitId
FROM fruits WHERE category_id = #{categoryId}
UNION ALL
SELECT beverage_id AS id, name, price, category_id AS categoryId, 'beverage' AS productType, beverage_id AS beverageId
FROM beverages WHERE category_id = #{categoryId}

mapper.update:
UPDATE products
SET name = #{name}, volume = #{volume}, price = #{price}, category_id = #{categoryId}, supplier_id = #{supplierId}
WHERE id = #{id}
